#!/usr/bin/env node
/**
 * Export the console's flows and catalogue as a bundle the JVM service
 * can execute, plus real decisions for it to reproduce.
 *
 * Run: npm run corpus:service
 *
 * The value and decision corpora are synthetic: small cases chosen to isolate
 * rules. This is the other kind of evidence — the actual flows the console
 * ships, the actual catalogue, and a sample of the actual decisions the
 * TypeScript engine produced from them. If the Kotlin service reproduces these
 * chain hashes over HTTP, the two engines agree on the product's own data and
 * not only on cases written to be agreed about.
 *
 * Emits two files:
 *   service-bundle.json  { artifacts, catalogue } — what the service loads
 *   service-cases.json   requests + the chain hash each must produce
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  catalogueSnapshot,
  execArtifacts,
  executeAt,
  DECISION_COUNT,
} from '../apps/console/mocks/fixtures/engine.ts';
import { requestHash } from '../packages/runtime/src/idempotency/index.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outDir = path.join(root, 'docs/conformance');
fs.mkdirSync(outDir, { recursive: true });

// --- Bundle -----------------------------------------------------------------

const bundle = {
  $comment:
    'GENERATED by scripts/build-service-bundle.mjs from the console fixtures. ' +
    'Loaded by engines/kotlin :service. Do not edit by hand.',
  artifacts: execArtifacts,
  catalogue: catalogueSnapshot,
};

fs.writeFileSync(
  path.join(outDir, 'service-bundle.json'),
  JSON.stringify(bundle, null, 2) + '\n',
  'utf8'
);

// --- Cases ------------------------------------------------------------------

/**
 * A spread across flows and outcomes rather than the first N.
 *
 * Taking a prefix would over-sample whichever flow happens to sort first
 * and would probably contain no suppressed decisions at all — and suppression
 * is where the frequency-policy and consent rules live, which are exactly the
 * ones a port gets wrong.
 */
const SAMPLE = 60;

// Executed here rather than read from an array of all 10,400, which no longer
// exists — see `executeAt` in the console's engine fixture. This script is the
// one caller that genuinely wants the whole corpus, and it is a build step, so
// it is the right place to pay for it.
const generated = Array.from({ length: DECISION_COUNT }, (_, i) => executeAt(i));

const offered = generated.filter((g) => g.trace.decision.winner !== null);
const suppressed = generated.filter((g) => g.trace.decision.winner === null);

function spread(list, n) {
  if (list.length <= n) return list;
  const step = list.length / n;
  return Array.from({ length: n }, (_, i) => list[Math.floor(i * step)]);
}

const sample = [
  ...spread(offered, Math.ceil(SAMPLE / 2)),
  ...spread(suppressed, Math.floor(SAMPLE / 2)),
].sort((a, b) => a.trace.id.localeCompare(b.trace.id));

const cases = sample.map(({ trace, request, artifact }) => ({
  artifactId: artifact.id,
  request,
  expected: {
    id: trace.id,
    chainHash: trace.chainHash,
    inputSnapshotHash: trace.decision.inputSnapshotHash,
    catalogueSnapshotHash: trace.decision.catalogueSnapshotHash,
    winner: trace.decision.winner,
    // Idempotency only works across instances if both engines agree on what
    // "the same request" is. Chain-hash agreement does not imply it: the
    // request hash covers a different set of fields, computed in a different
    // place, and could drift without a single decision hash changing.
    requestHash: requestHash(request),
  },
}));

const distinct = new Set(cases.map((c) => c.expected.chainHash));
if (distinct.size !== cases.length) {
  throw new Error(
    `Sample contains duplicate decisions (${cases.length - distinct.size}); the spread is not spreading`
  );
}

const withOffer = cases.filter((c) => c.expected.winner !== null).length;
if (withOffer === 0 || withOffer === cases.length) {
  throw new Error(
    'Sample is all-offered or all-suppressed; it would not exercise the frequency policy and consent rules'
  );
}

fs.writeFileSync(
  path.join(outDir, 'service-cases.json'),
  JSON.stringify(
    {
      $comment:
        'GENERATED by scripts/build-service-bundle.mjs. Real decisions from the ' +
        'console fixtures, for the JVM service to reproduce over HTTP.',
      algorithm: 'sha256',
      cases,
    },
    null,
    2
  ) + '\n',
  'utf8'
);

console.log(
  `Wrote docs/conformance/service-bundle.json: ${execArtifacts.length} artifacts, ` +
    `${catalogueSnapshot.offers.length} offers, ` +
    `${catalogueSnapshot.connectors.length} connectors.`
);
console.log(
  `Wrote docs/conformance/service-cases.json: ${cases.length} decisions ` +
    `(${withOffer} offered, ${cases.length - withOffer} suppressed).`
);
